from itertools import product
from typing import Sequence
Edge = tuple[int, int]

def count(vertex_count: int, edges: Sequence[Edge], k: int) -> int:
    return sum(all(a[u] != a[v] for u, v in edges)
               for a in product(range(k), repeat=vertex_count))

def threshold(vertex_count: int, edges: Sequence[Edge]) -> int:
    for k in range(3, max(3, vertex_count) + 1):
        if count(vertex_count, edges, k) > 0:
