    triangle = ((0, 1), (1, 2), (0, 2))
    print("triangle threshold:", threshold(3, triangle))
    print("triangle counts:", [count(3, triangle, k) for k in range(3, 7)])

from typing import Iterable
Edge = tuple[int, int]

def clique_count(n: int, k: int) -> int:
    """Chromatic count for K_n: the falling factorial k(k-1)...(k-n+1)."""
    result = 1
    for i in range(n):
        result *= k - i
    return result if k >= n else 0

def friendship_count(n: int, k: int) -> int:
    return k * (k - 1) ** n * (k - 2) ** n

if __name__ == "__main__":
    for name, value in (("F_4", friendship_count(4, 6)),
                        ("K_7", clique_count(7, 6))):
        print(name, "P_G(6) =", value, "six labels suffice =", value > 0)

